CASE WHEN I.INVTN_STTS_CD = #{pendingCd} AND I.INVTN_EXPRY_DT <= #{now} THEN #{expiredCd}
     ELSE I.INVTN_STTS_CD
END

CASE WHEN T.ACPT_YN = 'Y' THEN #{acceptedCd}
     WHEN T.ACPT_YN = 'N' THEN #{rejectedCd}
     WHEN I.INVTN_STTS_CD = #{pendingCd} AND I.INVTN_EXPRY_DT <= #{now} THEN #{expiredCd}
     ELSE I.INVTN_STTS_CD
END

mapper.select:
/* 초대 대상 반려동물 번호 조회 */
SELECT PET_SN
  FROM INVTN_TRGT_PET
 WHERE JNT_BRUP_INVTN_SN = #{jntBrupInvtnSn}
 ORDER BY INVTN_TRGT_PET_SN

/* 같은 이메일·반려동물의 만료 전 대기 초대 만료일시 조회 */
SELECT MAX(I.INVTN_EXPRY_DT)
  FROM JNT_BRUP_INVTN I
  JOIN INVTN_TRGT_PET T
    ON T.JNT_BRUP_INVTN_SN = I.JNT_BRUP_INVTN_SN
 WHERE I.INVTN_TRGT_EML_HMAC = #{invtnTrgtEmlHmac}
   AND T.PET_SN = #{petSn}
   AND I.INVTN_STTS_CD = #{pendingCd}
   AND I.INVTN_EXPRY_DT > #{now}

mapper.insert:
/* 공동양육 초대 등록 */
INSERT INTO JNT_BRUP_INVTN
     ( SNDR_MBR_SN
     , RCVR_MBR_SN
     , INVTN_STTS_CD
     , INVTN_TRGT_EML_ENC
     , INVTN_TRGT_EML_HMAC
     , INVTN_EXPRY_DT
     , INVTN_TKN_HASH
     , REG_DT
     , MDFR_ID
     )
VALUES
     ( #{sndrMbrSn}
     , #{rcvrMbrSn}
     , #{invtnSttsCd}
     , #{invtnTrgtEmlEnc}
     , #{invtnTrgtEmlHmac}
     , #{invtnExpryDt}
     , #{invtnTknHash}
     , #{regDt}
     , #{mdfrId}
     )

/* 초대 대상 반려동물 등록 */
INSERT INTO INVTN_TRGT_PET
     ( JNT_BRUP_INVTN_SN
     , PET_SN
     )
VALUES
     ( #{jntBrupInvtnSn}
     , #{petSn}
     )

/* 공동양육 초대 상태 이력 등록 */
INSERT INTO JNT_BRUP_INVTN_STTS_HSTRY
     ( JNT_BRUP_INVTN_SN
     , MBR_SN
     , BFR_STTS_CD
     , AFTR_STTS_CD
     , CHG_RSN
     )
VALUES
     ( #{jntBrupInvtnSn}
     , #{mbrSn}
     , #{bfrSttsCd}
     , #{aftrSttsCd}
     , #{chgRsn}
     )

mapper.update:
/* 대기 초대 수락·거절 처리 */
UPDATE JNT_BRUP_INVTN
   SET INVTN_STTS_CD      = #{aftrSttsCd}
     , RCVR_MBR_SN        = #{rcvrMbrSn}
     , ACPT_RFSL_RSPNS_DT = NOW()
     , MDFR_ID            = #{actorId}
     , MDFCN_DT           = NOW()
 WHERE JNT_BRUP_INVTN_SN = #{jntBrupInvtnSn}
   AND INVTN_STTS_CD     = #{pendingCd}

/* 반려동물별 수락 여부 저장 (고른 반려동물 = 수락, 나머지 = 거절) */
UPDATE INVTN_TRGT_PET


   SET ACPT_YN = CASE WHEN PET_SN IN

                      #{petSn}

                      THEN 'Y'
                      ELSE 'N'
                 END


   SET ACPT_YN = 'N'


 WHERE JNT_BRUP_INVTN_SN = #{jntBrupInvtnSn}
